async function run() {
  const ids = Object.keys(TIPS);
  console.log(`${ids.length}개 레시피에 팁을 채웁니다...`);

  let updated = 0;
  for (const id of ids) {
    const { data, error } = await supabase.from('recipes').select('steps_json').eq('api_rcp_seq', id).single();
    if (error || !data) {
      console.error(`  [skip] ${id}: 조회 실패`, error?.message);
      continue;
    }

    const tips = TIPS[id];
    const nextSteps = data.steps_json.map((s, i) => (s.tip ? s : { ...s, tip: tips[i] || '' }));

    const { error: updateError } = await supabase.from('recipes').update({ steps_json: nextSteps }).eq('api_rcp_seq', id);
    if (updateError) {
      console.error(`  [fail] ${id}:`, updateError.message);
      continue;
    }
    updated++;
  }

  console.log(`완료: ${updated}/${ids.length}개 레시피 업데이트`);
}

run();
